INSERT INTO public.exercise_library (id, name, slug, body_area, movement_type, equipment, level, primary_muscles, secondary_muscles, instructions, image_paths, legacy_names) VALUES
  ('Band_Pull_Apart', 'Band Pull Apart', 'band-pull-apart', 'Shoulders', 'Pull', ARRAY['Band']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['middle back', 'traps']::text[], ARRAY['Begin with your arms extended straight out in front of you, holding the band with both hands.', 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.', 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.', 'Pause as you complete the movement, returning to the starting position under control.']::text[], ARRAY['/exercises/band-pull-apart-1.webp', '/exercises/band-pull-apart-2.webp']::text[], ARRAY['Band pull-apart']::text[]),
  ('Bodyweight_Squat', 'Bodyweight Squat', 'bodyweight-squat', 'Legs & Glutes', 'Squat', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['glutes', 'hamstrings']::text[], ARRAY['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[], ARRAY['/exercises/bodyweight-squat-1.webp', '/exercises/bodyweight-squat-2.webp']::text[], ARRAY['Squat']::text[]),
  ('Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'butt-lift-bridge', 'Legs & Glutes', 'Hinge', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.']::text[], ARRAY['/exercises/butt-lift-bridge-1.webp', '/exercises/butt-lift-bridge-2.webp']::text[], ARRAY['Glute bridge']::text[]),
  ('Chin-Up', 'Chin-Up', 'chin-up', 'Back', 'Pull', ARRAY['Bar']::text[], 'Beginner', ARRAY['lats']::text[], ARRAY['biceps', 'forearms', 'middle back']::text[], ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/chin-up-1.webp', '/exercises/chin-up-2.webp']::text[], ARRAY['Chin-up']::text[]),
  ('Concentration_Curls', 'Concentration Curls', 'concentration-curls', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[], ARRAY['/exercises/concentration-curls-1.webp', '/exercises/concentration-curls-2.webp']::text[], ARRAY['Concentration curl']::text[]),
  ('Dead_Bug', 'Dead Bug', 'dead-bug', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.']::text[], ARRAY['/exercises/dead-bug-1.webp', '/exercises/dead-bug-2.webp']::text[], ARRAY['Dead bug']::text[]),
  ('Dumbbell_Bench_Press', 'Dumbbell Bench Press', 'dumbbell-bench-press', 'Chest', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['/exercises/dumbbell-bench-press-1.webp', '/exercises/dumbbell-bench-press-2.webp']::text[], ARRAY['Bench press']::text[]),
  ('Dumbbell_Bicep_Curl', 'Dumbbell Bicep Curl', 'dumbbell-bicep-curl', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/dumbbell-bicep-curl-1.webp', '/exercises/dumbbell-bicep-curl-2.webp']::text[], ARRAY['Biceps curl']::text[]),
  ('Dumbbell_Floor_Press', 'Dumbbell Floor Press', 'dumbbell-floor-press', 'Arms', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['triceps']::text[], ARRAY['chest', 'shoulders']::text[], ARRAY['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.', 'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.', 'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[], ARRAY['/exercises/dumbbell-floor-press-1.webp', '/exercises/dumbbell-floor-press-2.webp']::text[], ARRAY['Floor press']::text[]),
  ('Dumbbell_Flyes', 'Dumbbell Flyes', 'dumbbell-flyes', 'Chest', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY[]::text[], ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/dumbbell-flyes-1.webp', '/exercises/dumbbell-flyes-2.webp']::text[], ARRAY['Chest fly']::text[]),
  ('Dumbbell_Shoulder_Press', 'Dumbbell Shoulder Press', 'dumbbell-shoulder-press', 'Shoulders', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/dumbbell-shoulder-press-1.webp', '/exercises/dumbbell-shoulder-press-2.webp']::text[], ARRAY['Shoulder press']::text[]),
  ('Dumbbell_Shrug', 'Dumbbell Shrug', 'dumbbell-shrug', 'Back', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/dumbbell-shrug-1.webp', '/exercises/dumbbell-shrug-2.webp']::text[], ARRAY['Shrug']::text[]),
  ('Dumbbell_Step_Ups', 'Dumbbell Step Ups', 'dumbbell-step-ups', 'Legs & Glutes', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings']::text[], ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['/exercises/dumbbell-step-ups-1.webp', '/exercises/dumbbell-step-ups-2.webp']::text[], ARRAY['Dumbbell step-up']::text[]),
  ('Farmers_Walk', 'Farmer''s Walk', 'farmers-walk', 'Full Body', 'Carry', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['forearms']::text[], ARRAY['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps']::text[], ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], ARRAY['/exercises/farmers-walk-1.webp', '/exercises/farmers-walk-2.webp']::text[], ARRAY['Farmer carry']::text[]),
  ('Front_Dumbbell_Raise', 'Front Dumbbell Raise', 'front-dumbbell-raise', 'Shoulders', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY[]::text[], ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[], ARRAY['/exercises/front-dumbbell-raise-1.webp', '/exercises/front-dumbbell-raise-2.webp']::text[], ARRAY['Front raise']::text[]),
  ('Hammer_Curls', 'Hammer Curls', 'hammer-curls', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/hammer-curls-1.webp', '/exercises/hammer-curls-2.webp']::text[], ARRAY['Hammer curl']::text[]),
  ('Incline_Dumbbell_Curl', 'Incline Dumbbell Curl', 'incline-dumbbell-curl', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/incline-dumbbell-curl-1.webp', '/exercises/incline-dumbbell-curl-2.webp']::text[], ARRAY['Incline curl']::text[]),
  ('Incline_Dumbbell_Press', 'Incline Dumbbell Press', 'incline-dumbbell-press', 'Chest', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[], ARRAY['/exercises/incline-dumbbell-press-1.webp', '/exercises/incline-dumbbell-press-2.webp']::text[], ARRAY['Incline press']::text[]),
  ('Incline_Push-Up', 'Incline Push-Up', 'incline-push-up', 'Chest', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.', 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.', 'Push body up until arms are extended. Repeat.']::text[], ARRAY['/exercises/incline-push-up-1.webp', '/exercises/incline-push-up-2.webp']::text[], ARRAY['Incline push-up']::text[]),
  ('Mountain_Climbers', 'Mountain Climbers', 'mountain-climbers', 'Legs & Glutes', 'Pull', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['chest', 'hamstrings', 'shoulders']::text[], ARRAY['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.', 'Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[], ARRAY['/exercises/mountain-climbers-1.webp', '/exercises/mountain-climbers-2.webp']::text[], ARRAY['Mountain climber']::text[]),
  ('One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'one-arm-dumbbell-row', 'Back', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['middle back']::text[], ARRAY['biceps', 'lats', 'shoulders']::text[], ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[], ARRAY['/exercises/one-arm-dumbbell-row-1.webp', '/exercises/one-arm-dumbbell-row-2.webp']::text[], ARRAY['One-arm row']::text[]),
  ('Plank', 'Plank', 'plank', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], ARRAY['/exercises/plank-1.webp', '/exercises/plank-2.webp']::text[], ARRAY['Front plank']::text[]),
  ('Pullups', 'Pullups', 'pullups', 'Back', 'Pull', ARRAY['Bar']::text[], 'Beginner', ARRAY['lats']::text[], ARRAY['biceps', 'middle back']::text[], ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/pullups-1.webp', '/exercises/pullups-2.webp']::text[], ARRAY['Pull-up']::text[]),
  ('Pushups', 'Pushups', 'pushups', 'Chest', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], ARRAY['/exercises/pushups-1.webp', '/exercises/pushups-2.webp']::text[], ARRAY['Push-up']::text[]),
  ('Pushups_Close_and_Wide_Hand_Positions', 'Pushups (Close and Wide Hand Positions)', 'pushups-close-and-wide-hand-positions', 'Chest', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/pushups-close-and-wide-hand-positions-1.webp', '/exercises/pushups-close-and-wide-hand-positions-2.webp']::text[], ARRAY['Close-grip push-up']::text[]),
  ('Reverse_Crunch', 'Reverse Crunch', 'reverse-crunch', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.', 'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.', 'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/reverse-crunch-1.webp', '/exercises/reverse-crunch-2.webp']::text[], ARRAY['Reverse crunch']::text[]),
  ('Reverse_Flyes', 'Reverse Flyes', 'reverse-flyes', 'Shoulders', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY[]::text[], ARRAY['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/reverse-flyes-1.webp', '/exercises/reverse-flyes-2.webp']::text[], ARRAY['Reverse fly']::text[]),
  ('Side_Lateral_Raise', 'Side Lateral Raise', 'side-lateral-raise', 'Shoulders', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY[]::text[], ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/side-lateral-raise-1.webp', '/exercises/side-lateral-raise-2.webp']::text[], ARRAY['Lateral raise']::text[]),
  ('Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'single-leg-glute-bridge', 'Legs & Glutes', 'Hinge', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.']::text[], ARRAY['/exercises/single-leg-glute-bridge-1.webp', '/exercises/single-leg-glute-bridge-2.webp']::text[], ARRAY['Single-leg glute bridge']::text[]),
  ('Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'split-squat-with-dumbbells', 'Legs & Glutes', 'Squat', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['glutes', 'hamstrings']::text[], ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], ARRAY['/exercises/split-squat-with-dumbbells-1.webp', '/exercises/split-squat-with-dumbbells-2.webp']::text[], ARRAY['Dumbbell split squat']::text[])
